// # 三个主入口；缸内数据、名单和快捷记录集中在缸详情。
import { historyTimeline, timelineMarkup } from './timeline.js';
import { TYPES, countLabel, shortCountLabel, membersFor, isBlackShrimp, diaryName, diaryNameLength, orderedContainers } from './data.js';
import { escapeHTML as e, dayLabel, localDate, timeLabel, relativeTime, latestRecord, recordSummary, filterRecords, careMonth, CARE_TYPES } from './logic.js';
import { icon, aquariumArt, animalIcon } from './art.js';
import { options } from './forms.js';
import { APP_VERSION } from './version.js';
import { PET_GROUPS, PET_TEMPLATES, petIcon, inferPetTemplate } from './pets.js';
import { HABITATS, habitatArt } from './habitats.js';
import { taskStates } from './tasks.js';
import { compareAppVersions } from './updates.js';
import { speciesGroups, memberSortKey, CLEAN_RECORDS_COPY, START_EMPTY_COPY } from './species.js';
export const NAV = [['home', '首页', 'home'], ['history', '记录', 'book'], ['residents', '居民', 'fish']];
const heading = (title, action = '', sub = '') => `<div class="page-heading"><div><h1>${e(title)}</h1>${sub ? `<p>${e(sub)}</p>` : ''}</div>${action}</div>`;
const addButton = (action, label, extra = '') => `<button class="button secondary small" data-action="${action}" ${extra}>${icon('plus', 15)}${label}</button>`;
export function emptyState(title, action = '') {
  return `<div class="empty-state">${animalIcon('fish', 48)}<p>${e(title)}</p>${action}</div>`;
}
export function shell(data, view, issue) {
  const pages = { home: homePage, history: historyPage, residents: residentsPage, tank: tankPage };
  const active = view.page === 'tank' ? 'home' : view.page;
  const due = taskStates(data).filter(task => task.state === 'due').length;
  const nav = size => NAV.map(([id, label, glyph]) => `<a href="#${id}" class="${active === id ? 'active' : ''}" ${active === id ? 'aria-current="page"' : ''}>${icon(glyph, size)}<span>${label}</span></a>`).join('');
  return `<header class="site-header"><div class="header-inner"><button type="button" class="brand diary-title ${diaryNameLength(diaryName(data))>12?'long-title':''}" data-action="edit-diary-name" aria-label="编辑日记名称：${e(diaryName(data))}"><span class="diary-name">${e(diaryName(data))}</span>${icon('pen',12)}</button><nav class="desktop-nav" aria-label="主要导航">${nav(18)}</nav><button class="icon-button reminder-button" data-action="reminders" aria-label="任务提醒">${icon('bell', 21)}${due ? `<span class="reminder-badge">${due > 99 ? '99+' : due}</span>` : ''}</button><button class="icon-button manager-button" data-action="manager" aria-label="管理与备份">${icon('gear', 21)}</button></div></header><main id="main" tabindex="-1" class="main-wrap">${issue ? `<div class="storage-banner" role="alert"><span>${e(issue)}</span><button class="button small secondary" data-action="raw-export">导出原始数据</button></div>` : ''}${(pages[view.page] || homePage)(data, view)}</main><nav class="bottom-nav" aria-label="手机导航">${nav(23)}</nav>`;
}
// # 两个页面共用物种与颜色顺序；每个颜色仍可进入原资料编辑。
const sortAttributes = (kind, containerId, species = '', axis = 'horizontal') => `data-sort-list="${kind}" data-container="${e(containerId)}" data-species="${e(species)}" data-sort-axis="${axis}"`;
function variantIcons(group, size = 32) {
  return `<span class="species-variants" ${sortAttributes('variants',group.containerId,group.key)}>${group.variants.map(id => `<button type="button" class="variant-icon" data-sort-item="${e(id)}" data-action="edit-species-group" data-container="${e(group.containerId)}" data-species="${e(group.key)}" data-template="${e(id)}" aria-label="编辑${e(group.name)}，${e(PET_TEMPLATES.find(p=>p.id===id)?.name || '自选形象')}">${petIcon(id,size)}</button>`).join('')}</span>`;
}
function animalChip(group) {
  return `<div class="animal-chip" data-sort-item="${e(group.key)}">${variantIcons(group)}<button type="button" class="animal-chip-label" data-action="edit-species-group" data-container="${e(group.containerId)}" data-species="${e(group.key)}" aria-label="修改${e(group.name)}及数量"><span>${e(group.name)}${group.uncertain ? '<i class="uncertain-dot" title="物种待确认"></i>' : ''}</span><b>${e(group.count)}</b></button></div>`;
}
export function quickActions(cid) {
  return `<div class="quick-actions">${['feed', 'siphon', 'topup', 'water', 'observe'].map(type => `<button data-action="record" data-type="${type}" data-container="${e(cid)}" class="quick-${type}" aria-label="${TYPES[type].label}">${icon(TYPES[type].icon, 21)}<span>${TYPES[type].label}</span></button>`).join('')}</div>`;
}
function lastCare(data, cid) {
  return `<div class="last-care">${[['feed', '喂食'], ['water', '换水']].map(([type, label]) => `<span>${label}<b>${e(relativeTime(latestRecord(data, cid, type)?.timestamp))}</b></span>`).join('')}</div>`;
}
// # 首尾按钮保持位置且禁用，移动使用所有缸的全局顺序，居民筛选不改变含义。
function containerOrderButtons(container, index, total) {
  if (total < 2) return '';
  return `<div class="container-order" role="group" aria-label="调整${e(container.name)}的顺序，当前第${index+1}个，共${total}个">${[[-1,'上移',index===0],[1,'下移',index===total-1]].map(([direction,label,disabled]) => `<button type="button" id="container-move-${encodeURIComponent(container.id)}-${direction}" class="icon-button container-move" data-action="move-container" data-id="${e(container.id)}" data-direction="${direction}" aria-label="${label}${e(container.name)}" title="${disabled ? direction===-1?'已在最前面':'已在最后面' : label}" ${disabled?'disabled':''}>${icon('back',16)}</button>`).join('')}</div>`;
}
function containerCard(data, c, index, total) {
  const animals = data.animals.filter(a => a.containerId === c.id);
  return `<article class="tank-card" data-tank="${e(c.id)}" data-container-card="${e(c.id)}"><a class="tank-scene" href="#tank/${encodeURIComponent(c.id)}" aria-label="查看${e(c.name)}的月历和记录">${habitatArt(c.art, c.id, animals)}<span class="scene-tag">${icon(c.type === 'bucket' ? 'bucket' : 'tank', 13)}${c.type === 'bucket' ? '虾桶' : '鱼缸'}</span></a><div class="tank-body"><div class="tank-title"><a href="#tank/${encodeURIComponent(c.id)}"><h2>${e(c.name)}</h2>${icon('chevron', 13)}</a><div class="container-controls">${containerOrderButtons(c,index,total)}<button class="icon-button" data-action="edit-container" data-id="${e(c.id)}" aria-label="编辑${e(c.name)}">${icon('pen', 16)}</button></div></div>${c.dimensions || c.estimatedVolume ? `<p class="dimensions">${e([c.dimensions, c.estimatedVolume].filter(Boolean).join(' · '))}</p>` : ''}<div class="animal-chips" ${sortAttributes('species',c.id,'','both')}>${speciesGroups(data,c.id).map(animalChip).join('')}${!animals.length ? addButton('add-animal', '添加居民', `data-container="${e(c.id)}"`) : ''}</div>${lastCare(data, c.id)}${quickActions(c.id)}</div></article>`;
}
export function homePage(data) {
  const containers = orderedContainers(data);
  const title = `<div class="page-heading home-heading date-heading"><div><h1 class="sr-only">${e(diaryName(data))}</h1><p><time datetime="${localDate()}">${e(new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'}))}</time></p></div>${data.containers.length?addButton('add-container','添加缸'):''}</div>`;
  if (!data.containers.length) return `${title}<section class="welcome-card"><div class="welcome-scene">${habitatArt('meadow')}</div><div class="welcome-copy"><span class="eyebrow">一点陪伴，一点日常</span><h2>从一片小水域开始。</h2><p>创建你的缸，迎接第一位居民。</p><button class="button primary" data-action="add-container">${icon('plus', 17)}创建第一个缸</button><div class="welcome-pets">${['crucian', 'shrimp', 'guppy-gold'].map(id => petIcon(id, 49)).join('')}</div></div></section>`;
  const today = filterRecords(data, { from: localDate(), to: localDate() });
  // # 今天的数量与列表使用同一完整结果，编辑重排后也不隐藏第七条及后续记录。
  return `${title}${data.settings.reminders.length ? tasksPanel(data, true) : ''}<div class="tank-grid">${containers.map((c,index) => containerCard(data,c,index,containers.length)).join('')}</div><section class="today-section"><div class="section-toolbar"><h2>今天 <span class="count-tag">${today.length}</span></h2><a class="text-link" href="#history">全部记录 ${icon('chevron', 12)}</a></div><div class="panel">${today.length ? recordList(data, today, true) : '<p class="small-empty">今天暂无记录</p>'}</div></section>`;
}
export function recordList(data, records, compact = false, hideContainer = false) {
  const names = Object.fromEntries(data.containers.map(c => [c.id, c.name]));
  return `<div class="record-list">${records.map(r => { const summary = recordSummary(r); return `<article class="record-row" data-record="${e(r.id)}"><time datetime="${e(r.timestamp)}">${timeLabel(r.timestamp)}</time><span class="record-icon ${TYPES[r.type].color}">${icon(TYPES[r.type].icon, 18)}</span><div class="record-content"><div class="record-head"><strong>${TYPES[r.type].label}</strong>${hideContainer ? '' : `<span>${e(names[r.containerId])}</span>`}</div>${summary ? `<p>${e(summary)}</p>` : ''}${r.notes && r.notes !== summary ? `<p class="record-notes">${e(r.notes)}</p>` : ''}${r.photoIds?.length ? `<button class="photo-count" data-action="view-photos" data-id="${e(r.id)}">${icon('camera', 15)}${r.photoIds.length} 张照片</button>` : ''}</div><div class="record-controls"><button class="icon-button" data-action="edit-record" data-id="${e(r.id)}" aria-label="编辑${TYPES[r.type].label}记录">${icon('pen', 16)}</button></div></article>`; }).join('')}</div>`;
}
function groupedRecords(data, records, hideContainer = false) {
  const groups = new Map();
  records.forEach(r => { const day = localDate(r.timestamp); if (!groups.has(day)) groups.set(day, []); groups.get(day).push(r); });
  return [...groups].map(([day, items]) => `<section class="history-group"><h2 class="history-day">${day === localDate() ? '今天' : e(day.slice(5).replace('-', ' / '))}<span>${items.length} 条</span></h2><div class="panel">${recordList(data, items, false, hideContainer)}</div></section>`).join('');
}
export function historyPage(data, view) {
  const records = filterRecords(data, view.filters);
  const rangeInvalid = view.filters.from && view.filters.to && view.filters.from > view.filters.to;
  const active = Object.values(view.filters).some(Boolean);
  const timeline = historyTimeline(data,records,{day:view.historyDay,container:view.filters.container,limit:view.historyLimit});
  return `${heading('记录', addButton('choose-record', '记一笔'))}<div class="history-search-row"><label class="search-box">${icon('search', 19)}<input id="history-search" type="search" data-filter-field="search" value="${e(view.filters.search)}" placeholder="搜索关键词" aria-label="搜索记录关键词"></label><button class="button secondary" data-action="toggle-filters" aria-label="展开筛选" aria-expanded="${view.filtersOpen}">${icon('filter', 18)}筛选</button></div>${view.filtersOpen ? `<div class="panel history-filters">${[['container', '缸', [['', '全部'], ...orderedContainers(data).map(c => [c.id, c.name])]], ['type', '类型', [['', '全部'], ...Object.entries(TYPES).map(([id, v]) => [id, v.label])]]].map(([key, label, items]) => `<label class="field"><span>${label}</span><select data-filter-field="${key}">${options(items, view.filters[key])}</select></label>`).join('')}<label class="field"><span>开始日期</span><input type="date" data-filter-field="from" value="${e(view.filters.from)}"></label><label class="field"><span>结束日期</span><input type="date" data-filter-field="to" value="${e(view.filters.to)}"></label></div>` : ''}<div class="results-info"><span>${records.length} 条${active ? ' · 已筛选' : ''}</span>${active ? '<button class="text-link" data-action="clear-filters">清除筛选</button>' : ''}</div><div id="history-results">${rangeInvalid ? '<p class="inline-error" role="alert">开始日期不能晚于结束日期</p>' : data.containers.length ? timelineMarkup(timeline) : emptyState('先创建一个缸')}</div>`;
}
function memberCard(a, m, i, total) {
  return `<button class="member-card" data-sort-item="${e(memberSortKey(a.id,m.id))}" data-action="edit-member" data-animal="${e(a.id)}" data-member="${e(m.id)}" aria-label="编辑${e(m.name || `${a.species} ${i + 1}`)}名字和头像"><span class="member-avatar">${m.avatarId ? `<img data-photo-id="${e(m.avatarId)}" alt="${e(m.name || a.species)}的头像" loading="lazy">` : petIcon(m.templateId || a.templateId || inferPetTemplate(a.species, a.icon), 57)}</span><span class="member-name ${m.name ? '' : 'unnamed'}">${e(m.name || (total > 1 ? `居民 ${i + 1}` : '取个名字'))}</span>${m.length ? `<small>${e(m.length)}</small>` : ''}<span class="member-edit">${icon('pen', 12)}</span></button>`;
}
export function residentGroup(group) {
  return `<section class="resident-group" data-sort-item="${e(group.key)}"><div class="species-heading" data-sort-preview>${variantIcons(group,36)}<button type="button" class="species-name" data-action="edit-species-group" data-container="${e(group.containerId)}" data-species="${e(group.key)}"><strong>${e(group.name)}</strong>${group.uncertain ? '<small class="uncertain-badge">待确认</small>' : ''}</button><button class="species-count" data-action="edit-species-group" data-container="${e(group.containerId)}" data-species="${e(group.key)}" aria-label="编辑${e(group.name)}及数量">${e(group.count)}${icon('pen',13)}</button></div>${group.members.length ? `<div class="members-grid members-${group.members.length}" ${sortAttributes('members',group.containerId,group.key,'both')}>${group.members.map((item,index)=>memberCard(item.animal,item.member,index,group.members.length)).join('')}</div>` : ''}</section>`;
}
function residentGroups(data, containerId) {
  return `<div class="resident-groups" ${sortAttributes('species',containerId,'','vertical')}>${speciesGroups(data,containerId).map(residentGroup).join('') || '<p class="small-empty">暂无居民</p>'}</div>`;
}
export function residentsPage(data, view) {
  const all = orderedContainers(data), positions = new Map(all.map((c,index) => [c.id,index]));
  const containers = all.filter(c => !view.residentContainer || c.id === view.residentContainer);
  return `${heading('居民', `<div class="heading-actions">${addButton('add-animal', '添加居民')}</div>`, '')}${!data.containers.length ? emptyState('先创建一个缸，迎接你的居民', addButton('add-container', '创建缸')) : ''}<div class="container-tabs" aria-label="按缸查看居民">${[['', '全部'], ...orderedContainers(data).map(c => [c.id, c.name])].map(([id, name]) => `<button class="chip ${view.residentContainer === id ? 'selected' : ''}" data-action="resident-filter" data-id="${e(id)}" aria-pressed="${view.residentContainer === id}">${e(name)}</button>`).join('')}</div><div class="residents-grid">${containers.map(c => `<section class="panel resident-panel" data-container-card="${e(c.id)}"><div class="resident-panel-head"><a href="#tank/${encodeURIComponent(c.id)}"><h2>${e(c.name)}</h2>${icon('chevron', 13)}</a><div class="container-controls">${containerOrderButtons(c,positions.get(c.id),all.length)}<button class="icon-button" data-action="add-animal" data-container="${e(c.id)}" aria-label="为${e(c.name)}添加物种">${icon('plus', 17)}</button></div></div>${residentGroups(data,c.id)}</section>`).join('')}</div>`;
}
export function tankPage(data, view) {
  const c = data.containers.find(c => c.id === view.tankId);
  if (!c) return emptyState('这个缸已被移除', '<a class="button secondary" href="#home">返回首页</a>');
  const month = careMonth(data, c.id, view.month);
  const records = view.selectedDay ? month.records.filter(r => localDate(r.timestamp) === view.selectedDay) : month.records;
  const animals = data.animals.filter(a => a.containerId === c.id);
  return `<a class="back-link" href="#home" data-detail-back>${icon('back', 16)}返回</a>${heading(c.name, `<button class="icon-button" data-action="edit-container" data-id="${e(c.id)}" aria-label="编辑${e(c.name)}">${icon('pen', 18)}</button>`, [c.dimensions, c.estimatedVolume].filter(Boolean).join(' · '))}<div class="tank-detail-grid"><section class="tank-detail-main"><div class="panel detail-scene">${habitatArt(c.art, `detail-${c.id}`, animals)}${quickActions(c.id)}</div><section class="panel calendar-panel"><div class="calendar-heading"><h2>维护月历</h2><div class="month-control"><button class="icon-button" data-action="month" data-offset="-1" aria-label="上个月">${icon('back', 16)}</button><strong>${month.year} / ${String(month.month).padStart(2, '0')}</strong><button class="icon-button" data-action="month" data-offset="1" aria-label="下个月">${icon('chevron', 16)}</button></div></div><div class="month-stats">${CARE_TYPES.map(type=>`<div class="care-${type}"><strong>${icon(TYPES[type].icon,17)}<span>×${month.counts[type]}</span></strong><span>${TYPES[type].label}</span></div>`).join('')}</div><div class="calendar-grid care-calendar"><div class="weekdays">${['一', '二', '三', '四', '五', '六', '日'].map(day => `<span>${day}</span>`).join('')}</div>${Array.from({ length: month.leading }, () => '<span class="calendar-blank"></span>').join('')}${month.days.map(d => `<button class="calendar-day ${d.careCount ? 'has-care' : ''} ${d.date === localDate() ? 'today' : ''} ${d.date === view.selectedDay ? 'selected' : ''}" data-action="calendar-day" data-date="${d.date}" aria-label="${d.date}，${CARE_TYPES.map(type=>`${TYPES[type].label} ${d.counts[type]} 次`).join('，')}" aria-pressed="${d.date === view.selectedDay}"><span class="calendar-date">${d.day}</span><span class="calendar-care">${CARE_TYPES.filter(type=>d.counts[type]).map(type=>`<span class="care-mark care-${type}" data-care="${type}">${icon(TYPES[type].icon,12)}<span>×${d.counts[type]}</span></span>`).join('')}</span></button>`).join('')}</div><p class="calendar-legend">图标 × 次数<span>空白日期未记录这四项</span></p></section><section class="tank-records"><div class="section-toolbar"><h2>${view.selectedDay ? e(view.selectedDay.slice(5).replace('-', ' / ')) : '本月记录'} <span class="count-tag">${records.length}</span></h2>${view.selectedDay ? '<button class="text-link" data-action="clear-day">整月</button>' : `<button class="text-link" data-action="tank-history" data-container="${e(c.id)}">全部 ${icon('chevron', 12)}</button>`}</div>${records.length ? groupedRecords(data, records.slice(0, 50), true) : '<div class="panel"><p class="small-empty">暂无记录</p></div>'}${records.length > 50 ? `<button class="button secondary load-more" data-action="tank-history" data-container="${e(c.id)}">查看全部 ${records.length} 条</button>` : ''}</section></section><aside class="panel tank-residents"><div class="resident-panel-head"><h2>缸内居民</h2><button class="icon-button" data-action="add-animal" data-container="${e(c.id)}" aria-label="添加物种">${icon('plus', 17)}</button></div>${residentGroups(data,c.id)}<button class="button secondary other-record" data-action="reminders" data-container="${e(c.id)}">${icon('bell', 15)}任务提醒</button><button class="button secondary other-record" data-action="choose-record" data-container="${e(c.id)}">${icon('plus', 15)}其他记录</button></aside></div>`;
}
export function managerContent(data, update = {}) {
  return `<div class="manager-summary">${data.containers.length} 个缸 <span>·</span> ${data.records.length} 条记录</div><div class="manager-actions"><button class="button primary" data-action="export-json">${icon('export', 19)}备份（含照片）</button><button class="button secondary" data-action="import">${icon('upload', 19)}恢复备份</button><button class="button secondary" data-action="export-csv">${icon('book', 19)}导出记录表格</button></div><button class="button secondary install-entry" data-action="install-help">${icon('phone', 18)}添加到 iPhone 主屏幕</button><input id="import-file" type="file" accept=".json,application/json" hidden><p class="manager-note">数据与照片保存在当前浏览器。换网址或手机前先备份。</p>${updatePanel(update)}<details class="manager-danger"><summary>清理与重置</summary><div class="cleanup-choice"><button class="button danger-quiet" data-action="clear-records">${icon('trash', 16)}仅清空维护记录</button><p>${CLEAN_RECORDS_COPY}</p></div><div class="cleanup-choice"><button class="button danger-quiet" data-action="start-empty">重新开始 · 空白日记</button><p>${START_EMPTY_COPY}</p></div><p class="cleanup-note">两项操作均不能直接撤销，可先导出含照片备份。</p></details>`;
}

// # 发布文字一律转义，版本检查结果只替换自己的短面板。
export function updatePanel(state = {}) {
  const busy = ['checking', 'installing'].includes(state.phase);
  const available = state.latest && compareAppVersions(state.latest.version, APP_VERSION) > 0;
  const message = state.error || (state.phase === 'checking' ? '正在检查…' : state.phase === 'installing' ? state.progress || '正在准备新版…' : available ? `发现新版本 v${state.latest.version}` : state.latest ? compareAppVersions(state.latest.version, APP_VERSION) === 0 ? '已是最新版本' : '当前版本较新，无需更新' : '');
  return `<section class="app-update" data-update-panel aria-live="polite"><div class="app-update-head"><strong class="manager-version">当前 v${e(APP_VERSION)}</strong><button class="button small secondary" data-action="check-update" ${busy ? 'disabled' : ''}>检查更新</button></div>${message ? `<p class="update-status ${state.error ? 'is-error' : ''}">${e(message)}</p>` : ''}${available ? `<details class="update-notes"><summary>更新内容 · ${e(state.latest.date)}</summary>${state.latest.notes.map(([title, description]) => `<div><b>${e(title)}</b><p>${e(description)}</p></div>`).join('')}</details><button class="button primary update-install" data-action="install-update" ${busy ? 'disabled' : ''}>更新到 v${e(state.latest.version)}</button><p class="update-note">日记和照片会保留。</p>` : ''}<a class="text-link update-history" href="./intro.html#updates" target="_blank" rel="noopener">更新记录 ↗</a></section>`;
}

// # 提醒沿用三个主入口，管理收在独立弹窗；不会请求系统推送权限。
export function tasksPanel(data, compact = false, containerId = '') {
  const tasks = taskStates(data).filter(task => !containerId || task.containerId === containerId);
  const shown = compact ? tasks.filter(task => task.state !== 'paused').slice(0, 3) : tasks;
  const names = Object.fromEntries(data.containers.map(c => [c.id, c.name]));
  const rows = shown.map(task => {
    const paused = task.state === 'paused', due = task.state === 'due';
    const when = paused ? (task.resumeAt ? `暂停中 · ${localDate(task.resumeAt)} ${timeLabel(task.resumeAt)} 恢复` : '已暂停 · 手动恢复') : `${localDate(task.nextDue) === localDate() ? '今天' : localDate(task.nextDue).slice(5).replace('-', '/')} ${timeLabel(task.nextDue)}`;
    const canComplete = !paused && ['feed', 'siphon', 'water', 'topup'].includes(task.type) && localDate(task.nextDue) <= localDate();
    return `<article class="task-row ${due ? 'is-due' : ''} ${paused ? 'is-paused' : ''}" data-task="${e(task.id)}"><span class="task-glyph">${icon(TYPES[task.type].icon, 21)}</span><div class="task-copy"><strong>${e(task.title || TYPES[task.type].label)}<small>${e(names[task.containerId])}</small></strong><span>${due ? '到期 · ' : task.completed ? '下次 · ' : ''}${e(when)}${!compact ? ` · 每 ${task.days} 天` : ''}</span>${paused && task.pauseReason ? `<p>${e(task.pauseReason)}</p>` : ''}</div><div class="task-actions">${canComplete ? `<button class="button small primary" data-action="complete-reminder" data-id="${e(task.id)}">完成</button>` : ''}${!compact ? `<button class="button secondary small" data-action="edit-reminder" data-id="${e(task.id)}" aria-label="编辑${e(task.title || TYPES[task.type].label)}提醒">${icon('pen', 14)}编辑</button><button class="button secondary small" data-action="pause-reminder" data-id="${e(task.id)}" aria-label="${paused?'调整暂停':'暂停几天'}提醒">${icon('pause', 14)}${paused?'调整暂停':'暂停'}</button>${paused?`<button class="button secondary small" data-action="resume-reminder" data-id="${e(task.id)}" aria-label="${paused ? '恢复' : '暂停'}提醒">${icon('play',14)}立即恢复</button>`:''}` : ''}</div></article>`;
  }).join('');
  return `<section class="${compact ? 'panel task-panel' : 'task-manager'}" data-reminder-container="${e(containerId)}"><div class="section-toolbar"><h2>${compact ? '接下来' : '任务提醒'}</h2>${addButton(compact ? 'reminders' : 'add-reminder', compact ? '管理' : '创建提醒', containerId ? `data-container="${e(containerId)}"` : '')}</div>${rows || '<p class="small-empty">暂无进行中的提醒</p>'}${compact ? '' : `<div class="calendar-export"><button class="button secondary" data-action="export-calendar" ${!tasks.some(t => t.state !== 'paused' || t.resumeAt) ? 'disabled' : ''}>${icon('export', 17)}导出日历文件</button><p>日历不会随 App 任务自动更新。</p><details><summary>在 iPhone 日历中使用</summary><p>将 .ics 文件作为邮件附件，在苹果「邮件」中打开并导入。暂停或修改任务后，也需修改已导入的日历。</p></details></div>`}</section>`;
}
export function petGallery() {
  return `<div class="pet-categories pet-library">${PET_GROUPS.map(group=>`<section class="pet-category" data-pet-category="${group.id}" aria-labelledby="pet-gallery-${group.id}"><h3 id="pet-gallery-${group.id}">${group.label}</h3><div class="pet-gallery pet-family-grid">${group.families.map(family=>`<div class="pet-family ${family.templates.length>1?'pet-family-many':''}" data-pet-family="${family.id}">${family.templates.map(p=>`<button type="button" data-action="use-pet-template" data-template="${p.id}" aria-label="选择${e(p.name)}">${petIcon(p.id,64)}</button>`).join('')}</div>`).join('')}</div></section>`).join('')}</div>`;
}
